import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

export const PRODUCTS_TAG = 'products'

export type Product = {
  id: number
  name: string
  price: number
}

// Shared, cached catalog read. Every view that needs catalog data should call
// this so a single `revalidateTag('products', ...)` refreshes all of them.
export async function getCatalogProducts(): Promise<Product[]> {
  'use cache'
  cacheTag(PRODUCTS_TAG)
  cacheLife('hours')

  return getAllProducts()
}

