import { Suspense } from 'react'
import { revalidateTag } from 'next/cache'
import { getCatalogProducts, PRODUCTS_TAG } from '@/lib/catalog'

async function ProductTable() {
  const products = await getCatalogProducts()

  return (
    <table>
      <thead>
        <tr>
          <th align="left">ID</th>
          <th align="left">Name</th>
          <th align="right">Price</th>
        </tr>
      </thead>
      <tbody>
        {products.map((product) => (
          <tr key={product.id}>
            <td>{product.id}</td>
            <td>{product.name}</td>
            <td align="right">${product.price.toLocaleString('en-US')}</td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}

export default function Page() {
  async function syncLatestCatalog() {
    'use server'
    // Mark catalog data stale with stale-while-revalidate semantics: the
    // action returns immediately, views keep serving the cached catalog, and
    // fresh ERP/PIM data is recomputed in the background on the next request.
    revalidateTag(PRODUCTS_TAG, 'max')
  }

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncLatestCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <Suspense fallback={<p>Loading products...</p>}>
        <ProductTable />
      </Suspense>
    </main>
  )
}

